/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import ts from 'typescript'

const require = createRequire(import.meta.url)
const source = readFileSync('app/ContactForm.tsx', 'utf8')
const { outputText } = ts.transpileModule(source, {
  compilerOptions: { jsx: ts.JsxEmit.ReactJSX, module: ts.ModuleKind.CommonJS },
})
const componentModule = { exports: {} }
new Function('require', 'module', 'exports', outputText)(require, componentModule, componentModule.exports)
const form = componentModule.exports.default().props.children.find(child => child.type === 'form')
assert.equal(typeof form.props.action, 'function')
const fields = ['name', 'email', 'message']
const valid = { name: ' Ada ', email: ' ada@example.com ', message: ' Hello"'! '"' }
const logs = []
const originalLog = console.log
console.log = (...args) => logs.push(args)
try {
  await form.props.action(new FormData())
  assert.fail('Empty submissions must be rejected')
} catch (error) {
  assert.equal(error.message, 'Name, email, and message are required.')
}
try {
  for (const field of fields) {
    for (const invalid of [null, '', '   ', new Blob(['file'])]) {
      const data = new FormData()
      for (const key of fields) data.set(key, valid[key])
      if (invalid === null) data.delete(field)
      else data.set(field, invalid)
      await assert.rejects(form.props.action(data), /Name, email, and message are required/)
    }
  }
  assert.equal(logs.length, 0)
  const data = new FormData()
  for (const field of fields) data.set(field, valid[field])
  await form.props.action(data)
  assert.deepEqual(logs, [['Saving contact message:', { name: 'Ada', email: 'ada@example.com', message: 'Hello"'!'"' }]])
} finally {
  console.log = originalLog
}
console.log('Contact action checks passed: valid submission and 13 invalid submissions.')
NODE"
